    },
    {
      "card_ids": ["C08"],
      "claim": "SSR180711, a DABCO carbamate, showed high brain-to-plasma distribution ratios in rats after subcutaneous dosing, supporting CNS access for DABCO-containing scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A fluorophenyl-fused cyclic sulfone analogue crossed the blood-brain barrier with a brain/plasma concentration ratio near 1 after oral administration, indicating that the sulfone moiety does not preclude brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A fluorophenyl-containing basic amine radioligand reached 4.1%ID total brain uptake in cynomolgus monkey PET imaging, confirming high CNS penetration for a related lipophilic basic chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A close fluorophenyl/piperidine analogue had an estimated steady-state brain/plasma ratio of 35 in rats, indicating strong brain partitioning for this structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple transferable analogues combining DABCO, fluorophenyl, and/or cyclic sulfone motifs show good-to-high brain penetration, with no contradictory evidence.",
